/**
 * Post-build patch: bypass middleware for /api/v1/* so API routes are not
 * blocked by the "Dynamic require of middleware-manifest.json" crash on
 * Cloudflare Workers. Only the server handler is invoked for these paths.
 *
 * Exception: platform-owner API namespaces must still run Next middleware
 * (owner gate + rate-limit marker). Prefix list is shared with
 * `lib/platform-admin/platform-api-middleware-exceptions.cjs`.
 *
 * Patches .open-next/worker.js (generated by opennextjs-cloudflare build).
 *
 * Fail-closed: if worker.js exists, this script exits non-zero unless the
 * postcondition (segment-safe four-namespace exception expression) is met.
 * Missing worker.js remains a documented skip (exit 0) for pre-build runs.
 */

const fs = require("fs");
const path = require("path");
const {
  PLATFORM_OWNER_API_PREFIXES,
  buildIsPlatformOwnerApiPathExpression,
} = require("../lib/platform-admin/platform-api-middleware-exceptions.cjs");
const { buildLiteBypassGuardExpression } = require("../lib/api/lite-allow-list.cjs");

const DEFAULT_WORKER_PATH = path.join(__dirname, "..", ".open-next", "worker.js");

const ORIGINAL_MARKER =
  "            // - `Request`s are handled by the Next server\n            const reqOrResp = await middlewareHandler(request, env, ctx);";

const ALREADY_BYPASS_MARKER = 'url.pathname.startsWith("/api/v1/")';

const LEGACY_OWNER_PLATFORM_ONLY =
  /if \(url\.pathname\.startsWith\("\/api\/v1\/"\) && !url\.pathname\.startsWith\("\/api\/v1\/owner"\) && !url\.pathname\.startsWith\("\/api\/v1\/platform"\)\) \{\s*reqOrResp = request;/;

const BYPASS_BLOCK_RE =
  /if \(\s*url\.pathname\.startsWith\("\/api\/v1\/"\)[\s\S]*?reqOrResp = request;\s*\} else \{\s*(?:const \{ handler: middlewareHandler \} = await import\("\.\/middleware\/handler\.mjs"\);\s*)?reqOrResp = await middlewareHandler\(request, env, ctx\);\s*\}/;

/**
 * @param {string} ownerApiExpr
 * @returns {string}
 */
function buildBypassReplacement(ownerApiExpr) {
  const liteGuard = buildLiteBypassGuardExpression();
  return `            // Bypass middleware for /api/v1/* except platform-owner API namespaces (segment-safe)
            // Field-worker clients still get lite allow-list enforcement before bypass.
            let reqOrResp;
            if (url.pathname.startsWith("/api/v1/") && !(${ownerApiExpr})) {
                const liteDenied = ${liteGuard};
                reqOrResp = liteDenied || request;
            } else {
                const { handler: middlewareHandler } = await import("./middleware/handler.mjs");
                reqOrResp = await middlewareHandler(request, env, ctx);
            }`;
}

/**
 * @param {string} code
 * @returns {{ ok: true } | { ok: false, reason: string }}
 */
function verifyPlatformOwnerBypassPostcondition(code) {
  const ownerApiExpr = buildIsPlatformOwnerApiPathExpression("url.pathname");

  if (!code.includes('url.pathname.startsWith("/api/v1/")')) {
    return { ok: false, reason: 'missing url.pathname.startsWith("/api/v1/") bypass gate' };
  }

  if (!code.includes(ownerApiExpr)) {
    return {
      ok: false,
      reason: "missing generated segment-safe platform-owner exception expression from shared CJS source",
    };
  }

  if (!code.includes("lite_client_path_forbidden") || !code.includes("liteDenied")) {
    return {
      ok: false,
      reason: "missing field-worker lite allow-list guard in /api/v1 bypass block",
    };
  }

  for (const prefix of PLATFORM_OWNER_API_PREFIXES) {
    const exact = `url.pathname === ${JSON.stringify(prefix)}`;
    const child = `url.pathname.startsWith(${JSON.stringify(`${prefix}/`)})`;
    if (!code.includes(exact)) {
      return { ok: false, reason: `missing exact segment check for ${prefix}` };
    }
    if (!code.includes(child)) {
      return { ok: false, reason: `missing prefix+/ segment check for ${prefix}` };
    }
  }

  // Fail if an old naive owner+platform-only gate remains without admin aliases.
  if (
    LEGACY_OWNER_PLATFORM_ONLY.test(code) &&
    !code.includes('"/api/v1/admin/billing"') &&
    !code.includes('"/api/v1/admin/leads"')
  ) {
    return { ok: false, reason: "legacy owner+platform-only bypass still present" };
  }

  const bypassCount = (code.match(/\/\/ Bypass middleware for \/api\/v1\/\* except platform-owner API namespaces/g) || [])
    .length;
  if (bypassCount > 1) {
    return { ok: false, reason: `duplicated bypass block (count=${bypassCount})` };
  }

  return { ok: true };
}

/**
 * Apply patch transforms to worker source. Does not write disk.
 * @param {string} code
 * @returns {{ code: string, applied: boolean, mode: string }}
 */
function applyWorkerBypassPatch(code) {
  const ownerApiExpr = buildIsPlatformOwnerApiPathExpression("url.pathname");
  const replacement = buildBypassReplacement(ownerApiExpr);
  let next = code;
  let mode = "none";
  const alreadyOk = verifyPlatformOwnerBypassPostcondition(code).ok;

  if (!alreadyOk) {
    if (next.includes(ORIGINAL_MARKER)) {
      next = next.replace(ORIGINAL_MARKER, replacement);
      mode = "original-marker";
    } else if (BYPASS_BLOCK_RE.test(next)) {
      const liteGuard = buildLiteBypassGuardExpression();
      next = next.replace(
        BYPASS_BLOCK_RE,
        `if (url.pathname.startsWith("/api/v1/") && !(${ownerApiExpr})) {
                const liteDenied = ${liteGuard};
                reqOrResp = liteDenied || request;
            } else {
                const { handler: middlewareHandler } = await import("./middleware/handler.mjs");
                reqOrResp = await middlewareHandler(request, env, ctx);
            }`
      );
      mode = "upgrade-bypass-block";
    } else if (LEGACY_OWNER_PLATFORM_ONLY.test(next)) {
      const liteGuard = buildLiteBypassGuardExpression();
      next = next.replace(
        LEGACY_OWNER_PLATFORM_ONLY,
        `if (url.pathname.startsWith("/api/v1/") && !(${ownerApiExpr})) {\n                const liteDenied = ${liteGuard};\n                reqOrResp = liteDenied || request;`
      );
      mode = "upgrade-legacy-owner-platform";
    }
  }

  // Remove top-level import of middleware so it is only loaded for non-API requests
  const beforeImport = next;
  next = next.replace(
    /import \{ handler as middlewareHandler \} from "\.\/middleware\/handler\.mjs";\n/g,
    "// middleware loaded dynamically for non-API paths only\n"
  );
  if (next !== beforeImport && mode === "none") {
    mode = "strip-static-import";
  }

  // Stub global require for middleware-manifest
  const stubRequireMarker =
    "return runWithCloudflareRequestContext(request, env, ctx, async () => {\n            const response = maybeGetSkewProtectionResponse(request);";
  const stubRequireReplacement = `return runWithCloudflareRequestContext(request, env, ctx, async () => {
            if (typeof globalThis.require === "function") {
                const _origRequire = globalThis.require;
                globalThis.require = function (id) {
                    if (typeof id === "string" && id.includes("middleware-manifest")) return { version: 3, middleware: {}, functions: {}, sortedMiddleware: [] };
                    return _origRequire.apply(this, arguments);
                };
            }
            const response = maybeGetSkewProtectionResponse(request);`;
  if (next.includes(stubRequireMarker) && !next.includes("_origRequire")) {
    next = next.replace(stubRequireMarker, stubRequireReplacement);
    if (mode === "none") mode = "stub-require";
  }

  // Second-pass upgrade for naive owner+platform-only only when still failing postcondition
  if (!verifyPlatformOwnerBypassPostcondition(next).ok && LEGACY_OWNER_PLATFORM_ONLY.test(next)) {
    const liteGuard = buildLiteBypassGuardExpression();
    next = next.replace(
      LEGACY_OWNER_PLATFORM_ONLY,
      `if (url.pathname.startsWith("/api/v1/") && !(${ownerApiExpr})) {\n                const liteDenied = ${liteGuard};\n                reqOrResp = liteDenied || request;`
    );
    mode = "upgrade-legacy-owner-platform";
  }

  // Upgrade already-present bypass blocks that lack the lite allow-list guard.
  if (
    next.includes('url.pathname.startsWith("/api/v1/")') &&
    !next.includes("liteDenied") &&
    /if \(\s*url\.pathname\.startsWith\("\/api\/v1\/"\)[\s\S]*?reqOrResp = request;/.test(next)
  ) {
    const liteGuard = buildLiteBypassGuardExpression();
    next = next.replace(
      /if \(\s*url\.pathname\.startsWith\("\/api\/v1\/"\)[\s\S]*?reqOrResp = request;/,
      `if (url.pathname.startsWith("/api/v1/") && !(${ownerApiExpr})) {
                const liteDenied = ${liteGuard};
                reqOrResp = liteDenied || request;`
    );
    if (mode === "none" || mode === "already-satisfying") mode = "add-lite-guard";
  }

  const applied = next !== code;
  return { code: next, applied, mode: applied ? mode : "already-satisfying" };
}

/**
 * @param {string} [workerPath]
 * @returns {{ skipped: true, reason: string } | { skipped: false, mode: string, path: string }}
 */
function patchWorkerBypassApiMiddleware(workerPath = DEFAULT_WORKER_PATH) {
  if (!fs.existsSync(workerPath)) {
    return { skipped: true, reason: "worker_missing" };
  }

  const original = fs.readFileSync(workerPath, "utf8");
  const { code, applied, mode } = applyWorkerBypassPatch(original);
  const post = verifyPlatformOwnerBypassPostcondition(code);

  if (!post.ok) {
    const err = new Error(
      `patch-worker-bypass-api-middleware: FAIL postcondition (${post.reason}); ` +
        `worker exists but is incompatible or patch did not apply (mode=${mode}, applied=${applied})`
    );
    err.code = "WORKER_PATCH_POSTCONDITION";
    throw err;
  }

  if (code !== original) {
    fs.writeFileSync(workerPath, code, "utf8");
  }

  // Re-read and re-verify after write (idempotent / no duplicate)
  const written = fs.readFileSync(workerPath, "utf8");
  const postWrite = verifyPlatformOwnerBypassPostcondition(written);
  if (!postWrite.ok) {
    const err = new Error(
      `patch-worker-bypass-api-middleware: FAIL after write (${postWrite.reason})`
    );
    err.code = "WORKER_PATCH_POSTCONDITION";
    throw err;
  }

  return { skipped: false, mode: applied ? mode : "already-satisfying", path: workerPath };
}

function main() {
  const workerPath = process.env.AISTROYKA_WORKER_PATCH_PATH || DEFAULT_WORKER_PATH;
  try {
    const result = patchWorkerBypassApiMiddleware(workerPath);
    if (result.skipped) {
      console.warn("patch-worker-bypass-api-middleware: .open-next/worker.js not found, skip");
      process.exit(0);
    }
    console.log(
      "patch-worker-bypass-api-middleware: patched .open-next/worker.js (bypass /api/v1/* except segment-safe owner/platform/admin billing|leads)" +
        ` [mode=${result.mode}]`
    );
    process.exit(0);
  } catch (err) {
    console.error(err instanceof Error ? err.message : String(err));
    process.exit(1);
  }
}

module.exports = {
  DEFAULT_WORKER_PATH,
  ORIGINAL_MARKER,
  ALREADY_BYPASS_MARKER,
  buildBypassReplacement,
  verifyPlatformOwnerBypassPostcondition,
  applyWorkerBypassPatch,
  patchWorkerBypassApiMiddleware,
};

if (require.main === module) {
  main();
}
